mapper.select:
SELECT COUNT(1)
FROM `farm_chat_message` m
INNER JOIN `farm_chat_session` s ON s.id = m.session_id AND s.status = 1
WHERE m.media_url = #{mediaUrl} AND m.status = 1
  AND (
    #{admin} = TRUE
    OR s.farm_owner_id = #{userId}
    OR (s.member_user_id = #{userId} AND (
        (s.member_role = 'user' AND EXISTS (
            SELECT 1 FROM `farm_owner_user` fou
            WHERE fou.owner_user_id = s.farm_owner_id AND fou.user_id = #{userId}
        ))
        OR (s.member_role = 'technician' AND EXISTS (
            SELECT 1 FROM `farm_owner_technician` fot
            WHERE fot.owner_user_id = s.farm_owner_id
              AND fot.technician_user_id = #{userId} AND fot.status = 1
        ))
    ))
  )

SELECT * FROM `farm_chat_message`
WHERE session_id = #{sessionId} AND status = 1
AND id < #{beforeId}
AND id > #{afterId}

    ORDER BY id ASC
    ORDER BY id DESC

LIMIT #{limit}
